"""Provide the disposable D46 token-masking utility fixture."""

import logging

logger = logging.getLogger(__name__)


def mask_token(token, keep):
    """Mask every character when visible suffix length is zero or covers the whole token."""
    logger.info("d46_fixture_call case=token-masking")
    if keep <= 0 or keep >= len(token):
        return "*" * len(token)
    return "*" * (len(token) - keep) + token[-keep:]

